import { useState, useEffect } from "react";

function PostList({ selectedPost, onSelectPost, reload, categoryId }) {
    const [posts, setPosts] = useState([]);

    useEffect(() => {
        if (!categoryId) {
            setPosts([]); // не показуємо пости, якщо категорія не вибрана
            return;
        }

        const fetchPosts = async () => {
            try {
                const res = await fetch(`http://localhost:5000/api/posts?category_id=${categoryId}`);
                const data = await res.json();
                setPosts(data);
            } catch (err) {
                console.error("Помилка при завантаженні постів:", err);
                setPosts([]);
            }
        };

        fetchPosts();
    }, [reload, categoryId]);

    return (
        <div className="space-y-4">
            {posts.length === 0 ? (
                <p className="text-gray-500">У цій категорії поки що немає постів.</p>
            ) : (
                <ul className="space-y-3">
                    {posts.map(post => (
                        <li
                            key={post.id}
                            onClick={() => onSelectPost(post.id)}
                            className={`card-gradient p-4 rounded cursor-pointer ${selectedPost === post.id ? "ring-2 ring-blue-400" : ""
                                }`}
                        >
                            <h4 className="font-bold">{post.title}</h4>
                            <p className="text-gray-700 line-clamp-2">{post.content}</p>
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
}

export default PostList;
